    /**
     * 远程开会
     *
     * @return
     */
    @Override
    public boolean sendRemoteMeeting() {
        boolean result = true;
        List<SceneControlParam> msgList = new ArrayList<>();
        //唤醒设备
        SceneControlParam wakeUpDevice = new SceneControlParam();
        wakeUpDevice.setDeviceId("17326110351020zxcaw41125000000105");
        wakeUpDevice.setService(wakeUpApi);
        wakeUpDevice.setArgs(new HashMap<>());
        msgList.add(wakeUpDevice);
        //预约会议
        SceneControlParam scheduleMeeting = new SceneControlParam();
        scheduleMeeting.setDeviceId("17326110351020zxcaw41125000000105");
        scheduleMeeting.setService(remoteMeeting);
        scheduleMeeting.setArgs(getInitiateMeetingParams("BBX项目演示"));
        msgList.add(scheduleMeeting);
        //调用玩视中控能力，将输入3接到输出1
        SceneControlParam vedioSwitch = new SceneControlParam();
        vedioSwitch.setDeviceId("17327584361760zyzkzj0010000000096");
        vedioSwitch.setService(sceneSwitch);
        Map<String, Object> vsParam = new HashMap<>();
        vsParam.put("input", 3);
        vsParam.put("output", 1);
        vedioSwitch.setArgs(vsParam);
        msgList.add(vedioSwitch);

        for (SceneControlParam sceneControlParam : msgList) {
            String s = sendServiceControl(sceneControlParam);
            log.info("控制设备{}返回数据:{}", sceneControlParam.getDeviceId(), s);
            JSONObject jsonObject = JSON.parseObject(s);
            if (!jsonObject.getInteger("code").equals(200)) {
                log.error("设备控制失败！");
                result = false;
            }
        }
        return result;
    }

