    //预约会议
    private Map<String, Object> getRemoteMeetingParams(String starTime, String endTime, boolean astTempSiteInfo, String meetingName) {
        Map<String, Object> meetingParams = new HashMap<>();
        JSONObject jsonObject = JSON.parseObject(meetingParamStr);
        // 定义日期时间格式
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

        // 将字符串解析为LocalDateTime对象
        LocalDateTime star = LocalDateTime.parse(starTime, formatter);
        LocalDateTime end = LocalDateTime.parse(endTime, formatter);

        // 提取会议开始时间的年、月、日、时、分、秒
        int year = star.getYear();
        int month = star.getMonthValue();
        int day = star.getDayOfMonth();
        int hour = star.getHour();
        int minute = star.getMinute();
        int second = star.getSecond();
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("year", year);
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("month", month);
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("day", day);
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("hour", hour);
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("minute", minute);
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("second", second);
        //会议持续时间
        // 计算两个LocalDateTime对象之间的差异
        Duration duration = Duration.between(star, end);
        // 获取差异的分钟数
        long minutesBetween = duration.toMinutes();
        jsonObject.getJSONObject("stMcuCallsetInfo").put("uwDuration", minutesBetween);
        if (StringUtils.isNotBlank(meetingName))
            jsonObject.put("szName", meetingName);
        //临时会场信息
        if (astTempSiteInfo == true) {
            JSONArray astTempSiteInfoList = getAstTempSiteInfo();
            jsonObject.put("astTempSiteInfo", astTempSiteInfoList);
        }
        meetingParams.put("data", jsonObject.toJSONString());
        return meetingParams;
    }

    //发起会议
    private Map<String, Object> getInitiateMeetingParams(String meetingName) {
        Map<String, Object> meetingParams = new HashMap<>();
        JSONObject jsonObject = JSON.parseObject(meetingParamStr);
        // 获取当前时间
        LocalDateTime star = LocalDateTime.now();
        // 提取会议开始时间的年、月、日、时、分、秒
        int year = star.getYear();
        int month = star.getMonthValue();
        int day = star.getDayOfMonth();
        int hour = star.getHour();
        int minute = star.getMinute();
        int second = star.getSecond();
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("year", year);
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("month", month);
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("day", day);
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("hour", hour);
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("minute", minute);
        jsonObject.getJSONObject("stMcuCallsetInfo").getJSONObject("stPreTime").put("second", second);
        //会议名称
        if (StringUtils.isNotBlank(meetingName))
            jsonObject.put("szName", meetingName);
        //会议模式0：召集
        jsonObject.getJSONObject("stMcuCallsetInfo").put("ucPreType", 0);
        //持续时间0
        jsonObject.getJSONObject("stMcuCallsetInfo").put("uwDuration", 0);
        //临时会场信息
        JSONArray astTempSiteInfoList = getAstTempSiteInfo();
        jsonObject.put("astTempSiteInfo", astTempSiteInfoList);
        meetingParams.put("data", jsonObject.toJSONString());
        return meetingParams;
    }


