    private String requestSessionAndLogin() {
        //发起请求
        String requestUrl = "https://10.10.58.102/api/auth/login/challenge?username=admin";
        log.info("请求鉴权接口：{}", requestUrl);
        HttpResponse response = HttpRequest.get(requestUrl)
                .execute();
        log.info("鉴权接口返回数据：{}", response);
        if (response.isOk()) {
            JSONObject body = JSONObject.parseObject(response.body());
            String session_id = body.getString("session_id");
            String challenge = body.getString("challenge");
            String salt = body.getString("salt");
            //获取到凭证请求登录接口
            String loginurl = "https://10.10.58.102/api/auth/login";
            //拼装请求参数
            log.info("请求登录接口：{}", loginurl);
            JSONObject requestJson = new JSONObject();
            requestJson.put("session_id", session_id);
            requestJson.put("username", "admin");
            String encryptPassword = encryptPassword("Ptac@2024", challenge, salt);
            requestJson.put("password", encryptPassword);
            log.info("请求登录请求参数：{}", requestJson.toJSONString());
            //登录接口
            HttpResponse execute = HttpRequest.post(loginurl)
                    .header("Content-Type", "application/json")
                    .body(requestJson.toJSONString())
                    .execute();
            if (execute.isOk()) {
                JSONObject loginBody = JSONObject.parseObject(execute.body());
                log.info("登录接口返回数据：{}", loginBody.toJSONString());
                if (loginBody.getInteger("status").equals(200)) {
                    String sessionID = loginBody.getString("session_id");
                    return sessionID;
                } else {
                    log.error("登陆失败！");
                    throw GenericException.fail("登陆失败，请检查登录配置");
                }
            } else {
                log.info("旷世登录请求失败！！！请检查账号信息");
                throw GenericException.fail("旷世登录请求失败！！");
            }
        } else {
            log.info("旷世鉴权请求失败！！！请检查设备状态");
            throw GenericException.fail("鉴权接口请求失败！！");
        }
    }

    /**
     * 密码加密
     *
     * @param password  原文密码
     * @param challenge 鉴权返回的32位随机数
     * @param salt      鉴权返回的2、64或128位的UUID或者随机数
     * @return
     */
    private String encryptPassword(String password, String challenge, String salt) {
        //加密原文组装
        String encrypeStr = password + salt + challenge;
        String encryptPassword = sha256(encrypeStr);
        return encryptPassword;
    }

    /**
     * sha256加密
     *
     * @param input 需要加密的原字符
     * @return
     */
    public static String sha256(String input) {
        try {
            // 获取SHA-256 MessageDigest实例
            MessageDigest digest = MessageDigest.getInstance("SHA-256");

            // 将输入字符串转换为字节数组，并进行更新
            byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));

            // 将字节数组转换为十六进制字符串
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            log.error("sha256字符转换失败!", e);
            throw GenericException.fail("sha256字符转换失败");
        }
    }
